{
  "predictors": [
    {
      "name": "Earnings Stability Surprise",
      "construction": "Calculate the standard deviation of quarterly earnings over the past five years and compare it to analyst forecast dispersion in the last quarter.",
      "rationale": "Stocks with unexpectedly stable earnings compared to analyst forecasts might be undervalued due to mispricing of risk.",
      "higher_returns_for": "stocks with lower-than-expected earnings volatility."
    },
    {
      "name": "Innovation Intensity Change",
      "construction": "Compute the change in R&D expense as a percentage of sales over the last three years.",
      "rationale": "Firms increasing their innovation efforts could be positioning for future growth, which the market might not immediately price in.",
      "higher_returns_for": "stocks with a significant increase in R&D intensity."
    },
    {
      "name": "Social Media Sentiment Divergence",
      "construction": "Analyze the sentiment score of a stock from social media platforms over the past year and compare it to analyst ratings.",
      "rationale": "Discrepancies between analyst assessments and broader public sentiment may indicate mispricing.",
      "higher_returns_for": "stocks with positive social sentiment and neutral or negative analyst ratings."
    },
    {
      "name": "Environmental Compliance Lag",
      "construction": "Measure the time lag between new environmental regulations and firm compliance announcements.",
      "rationale": "Firms quicker to comply may avoid future regulatory costs and disruptions, thus offering better risk-adjusted returns.",
      "higher_returns_for": "stocks with shorter compliance lags."
    },
    {
      "name": "Supplier Dependency Ratio",
      "construction": "Calculate the ratio of purchases from top three suppliers to total cost of goods sold, using the last fiscal year data.",
      "rationale": "Firms less dependent on a few suppliers might have better supply chain resilience and negotiating power.",
      "higher_returns_for": "stocks with lower supplier dependency ratios."
    },
    {
      "name": "Board Diversity Progression",
      "construction": "Compute the annual change in diversity percentage on the board over the past three years.",
      "rationale": "Increasing board diversity could lead to better decision-making and improved firm performance.",
      "higher_returns_for": "stocks with increasing board diversity percentages."
    },
    {
      "name": "Customer Satisfaction Momentum",
      "construction": "Track the changes in customer satisfaction scores over the last four quarters.",
      "rationale": "Improving customer satisfaction may signal future revenue growth and competitive strength.",
      "higher_returns_for": "stocks with increasing customer satisfaction scores."
    },
    {
      "name": "Patent Citation Growth",
      "construction": "Calculate the annual growth rate of patent citations over the past three years.",
      "rationale": "Firms with growing patent citations could enjoy stronger intellectual property advantages and future cash flows.",
      "higher_returns_for": "stocks with high patent citation growth rates."
    },
    {
      "name": "Corporate Wellness Initiatives",
      "construction": "Count the number of new wellness programs introduced in the last two years.",
      "rationale": "Firms investing in employee wellness might experience improved productivity and reduced turnover costs.",
      "higher_returns_for": "stocks with a higher rate of new wellness initiatives."
    },
    {
      "name": "Tax Efficiency Shift",
      "construction": "Calculate the year-over-year change in the effective tax rate over the past three years.",
      "rationale": "Improving tax efficiency can lead to higher net profits and shareholder returns.",
      "higher_returns_for": "stocks with decreasing effective tax rates."
    }
  ]
}
